33 /** Class to build a container representation from the contents of a jar file. */
34 public class JarFiles {
35
36   /**
37    * Generates a {@link JibContainerBuilder} from contents of a jar file.
38    *
39    * @param processor jar processor
40    * @param jarOptions jar cli options
41    * @param commonCliOptions common cli options
42    * @param commonContainerConfigCliOptions common command line options shared between jar and war
43    *     command
44    * @param logger console logger
45    * @return JibContainerBuilder
46    * @throws IOException if I/O error occurs when opening the jar file or if temporary directory
47    *     provided doesn't exist
48    * @throws InvalidImageReferenceException if the base image reference is invalid
49    */
50   public static JibContainerBuilder toJibContainerBuilder(
51       ArtifactProcessor processor,
52       Jar jarOptions,
53       CommonCliOptions commonCliOptions,
54       CommonContainerConfigCliOptions commonContainerConfigCliOptions,
55       ConsoleLogger logger)
56       throws IOException, InvalidImageReferenceException {
57
58     // Use AdoptOpenJDK image as the default base image.
59     JibContainerBuilder containerBuilder;
60     if (commonContainerConfigCliOptions.getFrom().isPresent()) {
61       containerBuilder =
62           ContainerBuilders.create(
63               commonContainerConfigCliOptions.getFrom().get(),
64               Collections.emptySet(),
65               commonCliOptions,
66               logger);
67     } else {
68       containerBuilder =
69           (processor.getJavaVersion() <= 8)
70               ? Jib.from("adoptopenjdk:8-jre")
71               : Jib.from("adoptopenjdk:11-jre");
72     }
73
74     List<FileEntriesLayer> layers = processor.createLayers();
75     List<String> customEntrypoint = commonContainerConfigCliOptions.getEntrypoint();
76     List<String> entrypoint =
77         customEntrypoint.isEmpty()
78             ? processor.computeEntrypoint(jarOptions.getJvmFlags())
79             : customEntrypoint;
80
81     containerBuilder
82         .setEntrypoint(entrypoint)
83         .setFileEntriesLayers(layers)
84         .setExposedPorts(commonContainerConfigCliOptions.getExposedPorts())
85         .setVolumes(commonContainerConfigCliOptions.getVolumes())
86         .setEnvironment(commonContainerConfigCliOptions.getEnvironment())
87         .setLabels(commonContainerConfigCliOptions.getLabels())
88         .setProgramArguments(commonContainerConfigCliOptions.getProgramArguments());
89     commonContainerConfigCliOptions.getUser().ifPresent(containerBuilder::setUser);
90     commonContainerConfigCliOptions.getFormat().ifPresent(containerBuilder::setFormat);
91     commonContainerConfigCliOptions.getCreationTime().ifPresent(containerBuilder::setCreationTime);
92
93     return containerBuilder;
94   }
95 }
